"""Independent sorted-key membership and all canonical row/unit marginals."""
from pathlib import Path
from datetime import datetime,timezone
import os,json,hashlib
import numpy as np,pandas as pd,zarr
from anndata._io.specs import read_elem

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    R=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);AR=Path(os.environ['PANCANCER_ANNOTATION_ROOT']);O=R/'all_CM_state_native_input_preflight_20261014_v1';inv=json.loads((O/'inventory.json').read_text());U=AR/'20261010_uniform_expression_annotation_v1';B=AR/'20261010_expression_annotation_downstream_v1';P=R/'immune_same_name_family_source_review_v1';files={'input_contract':U/'input_contract.json','original_catalogue':U/'all_node_number_catalog.tsv','current_catalogue':B/'downstream_review_v2/number_to_annotation_dictionary.tsv','counts':B/'inputs/sample_major_subcluster_counts.tsv','scope':P/'patient_block_provenance_overlay_v1/private_all1290_patient_provenance_overlay.tsv'}
    for k,p in files.items():assert sha(p)==inv['input_sha256'][k]
    assert sha(O/'private_canonical_row_selection.npz')==inv['private_row_selection_sha256'] and sha(O/'private_all_frozen_sample_node_units.tsv.gz')==inv['private_unit_table_sha256']
    units=pd.read_csv(O/'private_all_frozen_sample_node_units.tsv.gz',sep='\t',keep_default_na=False);scope=pd.read_csv(files['scope'],sep='\t',keep_default_na=False);counts=pd.read_csv(files['counts'],sep='\t',keep_default_na=False);counts=counts[counts.sampleID.isin(scope.sampleID)];current=pd.read_csv(files['current_catalogue'],sep='\t',keep_default_na=False).set_index('node_id');assert len(current)==172 and scope.sampleID.nunique()==1290;expected=counts.set_index(['sampleID','subCluster']);got=units.set_index(['sample_uid','subCluster']);assert got.index.is_unique and set(got.index)==set(expected.index);assert np.array_equal(got.n_cells,expected.loc[got.index].n_cells)
    for r in units.itertuples():assert r.subCluster==current.loc[r.node_id,'subCluster'] and r.major==current.loc[r.node_id,'majorCluster']
    contract=json.loads(files['input_contract'].read_text());g=zarr.open_group(contract['core_zarr'],mode='r');sample=pd.Categorical(read_elem(g['obs']['sample_uid']));node=pd.Categorical(read_elem(g['obs']['expression_v1_node_id']));si={str(v):i for i,v in enumerate(sample.categories)};ni={str(v):i for i,v in enumerate(node.categories)};keys=np.array([si[r.sample_uid]*len(node.categories)+ni[r.node_id] for r in units.itertuples()],np.int64);assert np.array_equal(keys,units.unit_key.to_numpy()) and len(np.unique(keys))==len(keys);allkeys=sample.codes.astype(np.int64)*len(node.categories)+node.codes;valid=(sample.codes>=0)&(node.codes>=0);sort=np.argsort(keys);ordered=keys[sort];membership=valid&np.isin(allkeys,ordered);fresh=np.flatnonzero(membership);z=np.load(O/'private_canonical_row_selection.npz',allow_pickle=False);assert np.array_equal(fresh,z['global_rows']);expected_units=sort[np.searchsorted(ordered,allkeys[fresh])];assert np.array_equal(expected_units,z['unit_index']);assert np.array_equal(np.bincount(expected_units,minlength=len(units)),units.n_cells.to_numpy())
    ss=units.groupby('gse_id',observed=True).n_cells.sum();public=pd.read_csv(O/'all_source_native_scope.tsv',sep='\t').set_index('gse_id');assert set(ss.index)==set(public.index) and np.array_equal(ss,public.loc[ss.index].selected_cells);assert len(fresh)==4532933 and units.sample_uid.nunique()==1290 and units.node_id.nunique()==172
    A=R/'all_CM_state_row_preflight_audit_20261014_v1';assert not A.exists();A.mkdir();out=dict(status='PASS_ALL4532933_CANONICAL_ROWS_ALL35567_UNITS_AND_FROZEN172_1290_SCOPE',observed_UTC=datetime.now(timezone.utc).isoformat(),auditor_sha256=sha(__file__),producer_inventory_sha256=sha(O/'inventory.json'),selected_cells=len(fresh),sample_node_units=len(units),sources=len(ss),libraries=1290,nodes=172,canonical_row_membership_independently_rebuilt=True,all_native_counts_marginals_exact=True,no_expression_copy_or_identity_change=True,formal_state_labels=False);(A/'independent_audit.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out))
if __name__=='__main__':main()
